bool PcPart::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("ID"))
    {
        if(!validJsonOfField(0, "ID", pJson["ID"], err, true))
            return false;
    }
    else
    {
        err="The ID column cannot be null";
        return false;
    }
    if(pJson.isMember("COSTCODE"))
    {
        if(!validJsonOfField(1, "COSTCODE", pJson["COSTCODE"], err, true))
            return false;
    }
    if(pJson.isMember("PARTCODE"))
    {
        if(!validJsonOfField(2, "PARTCODE", pJson["PARTCODE"], err, true))
            return false;
    }
    if(pJson.isMember("PARTNAME"))
    {
        if(!validJsonOfField(3, "PARTNAME", pJson["PARTNAME"], err, true))
            return false;
    }
    if(pJson.isMember("STATUS"))
    {
        if(!validJsonOfField(4, "STATUS", pJson["STATUS"], err, true))
            return false;
    }
    if(pJson.isMember("CREATEUSER"))
    {
        if(!validJsonOfField(5, "CREATEUSER", pJson["CREATEUSER"], err, true))
            return false;
    }
    if(pJson.isMember("CREATEDATE"))
    {
        if(!validJsonOfField(6, "CREATEDATE", pJson["CREATEDATE"], err, true))
            return false;
    }
    if(pJson.isMember("UPDATEUSER"))
    {
        if(!validJsonOfField(7, "UPDATEUSER", pJson["UPDATEUSER"], err, true))
            return false;
    }
    if(pJson.isMember("UPDATEDATE"))
    {
        if(!validJsonOfField(8, "UPDATEDATE", pJson["UPDATEDATE"], err, true))
            return false;
    }
    return true;
}
